   306	void Coap::HandleRetransmissionTimer(void)
   307	{
   308	    uint32_t now = TimerMilli::GetNow();
   309	    uint32_t nextDelta = 0xffffffff;
   310	    CoapMetadata coapMetadata;
   311	    Message *message = mPendingRequests.GetHead();
   312	    Message *nextMessage = NULL;
   313	    Ip6::MessageInfo messageInfo;
   314	
   315	    while (message != NULL)
   316	    {
   317	        nextMessage = message->GetNext();
   318	        coapMetadata.ReadFrom(*message);
   319	
   320	        if (coapMetadata.IsLater(now))
   321	        {
   322	            // Calculate the next delay and choose the lowest.
   323	            if (coapMetadata.mNextTimerShot - now < nextDelta)
   324	            {
   325	                nextDelta = coapMetadata.mNextTimerShot - now;
   326	            }
   327	        }
   328	        else if ((coapMetadata.mConfirmable) &&
   329	                 (coapMetadata.mRetransmissionCount < kMaxRetransmit))
   330	        {
   331	            // Increment retransmission counter and timer.
   332	            coapMetadata.mRetransmissionCount++;
   333	            coapMetadata.mRetransmissionTimeout *= 2;
   334	            coapMetadata.mNextTimerShot = now + coapMetadata.mRetransmissionTimeout;
   335	            coapMetadata.UpdateIn(*message);
   336	
   337	            // Check if retransmission time is lower than current lowest.
   338	            if (coapMetadata.mRetransmissionTimeout < nextDelta)
   339	            {
   340	                nextDelta = coapMetadata.mRetransmissionTimeout;
   341	            }
   342	
   343	            // Retransmit
   344	            if (!coapMetadata.mAcknowledged)
   345	            {
   346	                messageInfo.SetPeerAddr(coapMetadata.mDestinationAddress);
   347	                messageInfo.SetPeerPort(coapMetadata.mDestinationPort);
   348	                messageInfo.SetSockAddr(coapMetadata.mSourceAddress);
   349	
   350	                SendCopy(*message, messageInfo);
   351	            }
   352	        }
   353	        else
   354	        {
   355	            // No expected response or acknowledgment.
   356	            FinalizeCoapTransaction(*message, coapMetadata, NULL, NULL, NULL, OT_ERROR_RESPONSE_TIMEOUT);
   357	        }
   358	
   359	        message = nextMessage;
   360	    }

