293	    // validates that all included TLVs are properly formatted.
294	
295	    VerifyOrExit(Tlv::Find<MeshCoP::BorderAgentLocatorTlv>(aMsg.mMessage, borderAgentRloc) == kErrorNotFound);
296	
297	    SuccessOrExit(Tlv::Find<MeshCoP::CommissionerSessionIdTlv>(aMsg.mMessage, sessionId));
298	
299	    if (FindCommissioningSessionId(localSessionId) == kErrorNone)
300	    {
301	        VerifyOrExit(sessionId == localSessionId);
302	    }
303	
304	    // Add the Border Agent RLOC TLV from Network Data.
305	
306	    if (FindBorderAgentRloc(borderAgentRloc) == kErrorNone)
307	    {
308	        SuccessOrExit(Tlv::Append<MeshCoP::BorderAgentLocatorTlv>(aMsg.mMessage, borderAgentRloc));
309	    }
310	
311	    SuccessOrExit(SetCommissioningData(aMsg.mMessage));
312	
313	    state = MeshCoP::StateTlv::kAccept;
314	
315	exit:
316	    if (Get<Mle::Mle>().IsLeader())
317	    {
318	        SendCommissioningSetResponse(aMsg, state);
319	    }
320	}
